const students=$('تجميع الطلاب - trans').first().json.students||[];
const requests=$input.all().map(i=>i.json||{}).filter(r=>String(r['رقم الطلب']??'').trim());
const gradeMap={'730':'الأول متوسط','830':'الثاني متوسط','930':'الثالث متوسط'};
const maxMap={'730':6,'830':6,'930':6};
const grades={};
for(const [code,name] of Object.entries(gradeMap)){
 const classes={};for(let i=1;i<=maxMap[code];i++)classes[String(i)]=0;
 grades[name]={code,classes,total:0};
}
for(const s of students){
 const code=String(s['رقم الصف']??'').trim(), c=String(s['الفصل']??'').trim(), name=gradeMap[code];
 if(name&&c in grades[name].classes){grades[name].classes[c]++;grades[name].total++;}
}
function liveEval(r){
 const grade=String(r['الصف']??''), from=String(r['الفصل الحالي']??''), to=String(r['الفصل المطلوب']??'');
 const g=grades[grade];if(!g||!(from in g.classes)||!(to in g.classes)) return {score:0,label:'غير محسوب',suggestedClass:null};
 const counts={...g.classes}, vals=Object.values(counts), mean=vals.reduce((a,b)=>a+b,0)/vals.length;
 const variance=o=>Object.values(o).reduce((s,n)=>s+Math.pow(n-mean,2),0)/vals.length;
 const before=variance(counts), after={...counts};after[from]=Math.max(0,after[from]-1);after[to]++;
 const score=Math.round((before-variance(after))*10);
 const label=score>0?'يحسن الموازنة':score<0?'يزيد التفاوت':'محايد';
 const targets=Object.entries(counts).filter(([c])=>c!==from).sort((a,b)=>a[1]-b[1]);
 return {score,label,suggestedClass:targets[0]?.[0]??null};
}
const safe=requests.map(r=>{
 const e=liveEval(r);
 return {
  requestId:String(r['رقم الطلب']??''),studentId:String(r['رقم الطالب']??''),name:String(r['اسم الطالب']??''),
  grade:String(r['الصف']??''),gradeCode:String(r['رقم الصف']??''),fromClass:String(r['الفصل الحالي']??''),toClass:String(r['الفصل المطلوب']??''),
  reason:String(r['سبب الطلب']??''),note:String(r['ملاحظات الطالب']??''),date:String(r['تاريخ الطلب']??''),status:String(r['الحالة']??'قيد المراجعة'),
  balanceScore:e.score,balanceLabel:e.label,suggestedClass:e.suggestedClass,managementNote:String(r['ملاحظة الإدارة']??'')
 };
});
safe.sort((a,b)=>String(b.date).localeCompare(String(a.date)));
const summary={
 pending:safe.filter(r=>r.status==='قيد المراجعة').length,
 approved:safe.filter(r=>r.status==='مقبول').length,
 rejected:safe.filter(r=>r.status==='مرفوض').length
};
return [{json:{success:true,summary,grades,requests:safe}}];

const req=$('تحليل طلب trans').first().json;
const row=$input.first()?.json??{};
const id=String(row['رقم الطلب']??'').trim();
const status=String(row['الحالة']??'').trim();
const decision=req.decision;
let message='';
if(!id) message='لم يتم العثور على الطلب.';
else if(status!=='قيد المراجعة') message=`لا يمكن تعديل هذا الطلب لأن حالته الحالية: ${status}`;
else if(!['approve','reject'].includes(decision)) message='القرار غير صالح.';
else if(!req.staffName) message='اسم الموظف مطلوب.';
const now=new Date(Date.now()+3*60*60*1000),pad=n=>String(n).padStart(2,'0');
const decisionDate=`${now.getUTCFullYear()}-${pad(now.getUTCMonth()+1)}-${pad(now.getUTCDate())} ${pad(now.getUTCHours())}:${pad(now.getUTCMinutes())}`;
return [{json:{
 valid:!message,message,decision,requestId:id,studentId:String(row['رقم الطالب']??''),name:String(row['اسم الطالب']??''),
 fromClass:String(row['الفصل الحالي']??''),toClass:String(row['الفصل المطلوب']??''),note:req.note,staffName:req.staffName,decisionDate,
 newStatus:decision==='approve'?'مقبول':'مرفوض'
}}];

